import type { ComponentPropsWithRef, DragEvent, ReactNode } from 'react';
import type { StoreApi } from 'zustand/vanilla';
import type { FileTreeEmitter, FileTreeLoadReason } from './file-tree-events';

export type FileTreeFileStat = {
	directory: string;
	kind: 'directory' | 'file';
	meta: Record<string, unknown>;
	mtime: number;
	name: string;
	path: string;
	size: number;
};

export type FileTreeFileSystem = {
	readdir(path: string, options?: { signal?: AbortSignal }): Promise<FileTreeFileStat[]>;
};

export type FileTreeLimits = {
	maxCachedDirectories: number;
	maxConcurrency: number;
	maxDepth: number;
	maxNodes: number;
};

export type FileTreeLimitOptions = Partial<FileTreeLimits>;

export type FileTreeMessages = {
	collapse: string;
	empty: string;
	expand: string;
	loadError: (path: string, error: string) => string;
	loading: string;
	maxCachedDirectories: string;
	maxDepth: string;
	maxNodes: string;
	retry: string;
	treeLabel: string;
};

export type FileTreeDirectoryStatus = 'error' | 'idle' | 'loading' | 'queued' | 'ready';
export type FileTreeDirectoryErrorCode = 'load' | 'max-cached-directories' | 'max-nodes';

export type FileTreeDirectoryState = {
	entries: FileTreeFileStat[];
	lastAccess: number;
	path: string;
	status: FileTreeDirectoryStatus;
	error?: string;
	errorCode?: FileTreeDirectoryErrorCode;
	requestId?: number;
};

export type FileTreeSourceState = {
	directoriesOnly: boolean;
	fileSystem: FileTreeFileSystem;
	generation: number;
	rootPath: string;
};

export type FileTreeStoreState = {
	source: FileTreeSourceState;
	limits: FileTreeLimits;
	tree: {
		clock: number;
		directories: Map<string, FileTreeDirectoryState>;
		expanded: Set<string>;
		pendingRefresh: Set<string>;
		pendingRemoval: Set<string>;
	};
	selection: { path?: string };
	navigation: { currentPath: string };
	reveal: { status: 'error' | 'idle' | 'loading' | 'ready'; path?: string; error?: string };
	requests: { nextId: number };
	events: FileTreeEmitter;
	actions: FileTreeActions;
};

export type FileTreeActions = {
	beginRefresh: (
		paths: readonly string[],
		removedPaths: readonly string[],
		generation: number,
	) => { paths: string[]; removedPaths: string[] } | undefined;
	beginLoad: (path: string, generation: number) => number | undefined;
	beginReveal: (path: string, generation: number) => boolean;
	cancelLoad: (path: string, generation: number, requestId?: number) => boolean;
	collapse: (path: string) => void;
	completeLoad: (path: string, generation: number, requestId: number, entries: FileTreeFileStat[]) => boolean;
	completeReveal: (path: string, generation: number) => boolean;
	consumeRefresh: (generation: number) => { paths: string[]; removedPaths: string[] } | undefined;
	expand: (path: string) => void;
	failLoad: (
		path: string,
		generation: number,
		requestId: number,
		error: string,
		errorCode?: FileTreeDirectoryErrorCode,
	) => boolean;
	failReveal: (path: string, generation: number, error: string) => boolean;
	replaceSource: (options: FileTreeSourceOptions) => boolean;
	requestLoad: (path: string, reason?: FileTreeLoadReason) => void;
	requestNavigate: (path: string) => void;
	requestRefresh: (paths: readonly string[], options?: { removedPaths?: readonly string[] }) => void;
	requestReveal: (path: string) => void;
	requestSelection: (path?: string) => void;
	retry: (path: string) => void;
	syncCurrentPath: (path: string) => void;
	syncSelectedPath: (path?: string) => void;
	toggle: (path: string) => void;
	touch: (path: string) => void;
};

export type FileTreeSourceOptions = {
	directoriesOnly?: boolean;
	fileSystem: FileTreeFileSystem;
	limits?: FileTreeLimitOptions;
	rootPath?: string;
};

export type CreateFileTreeStoreOptions = FileTreeSourceOptions & {
	actions?: Partial<FileTreeActions>;
	currentPath?: string;
	selectedPath?: string;
};

export type FileTreeStore = StoreApi<FileTreeStoreState>;

export type FileTreeRenderNode = {
	children?: FileTreeRenderNode[];
	depth: number;
	entry: FileTreeFileStat;
	error?: string;
	errorCode?: FileTreeDirectoryErrorCode;
	id: string;
	isCurrent: boolean;
	kind: 'directory' | 'file';
	name: string;
	path: string;
	status: FileTreeDirectoryStatus;
};

export type FileTreeDropTarget =
	| { path: string; state: 'accepted' }
	| { path: string; reason: string; state: 'rejected' };

export type FileTreeProps = Omit<ComponentPropsWithRef<'div'>, 'children' | 'onSelect'> & {
	currentPath?: string;
	defaultCurrentPath?: string;
	defaultSelectedPath?: string;
	directoriesOnly?: boolean;
	dropTarget?: FileTreeDropTarget;
	/** @deprecated Use dropTarget to expose accepted and rejected target state. */
	dropTargetPath?: string;
	fileSystem: FileTreeFileSystem;
	height?: number;
	indent?: number;
	limits?: FileTreeLimitOptions;
	messages?: Partial<FileTreeMessages>;
	onActivate?: (entry: FileTreeFileStat) => void;
	onEntryDragEnd?: (entry: FileTreeFileStat, event: DragEvent<HTMLElement>) => void;
	onEntryDragStart?: (entry: FileTreeFileStat, event: DragEvent<HTMLElement>) => void;
	onEntryDragOver?: (entry: FileTreeFileStat, event: DragEvent<HTMLElement>) => void;
	onEntryDragLeave?: (entry: FileTreeFileStat, event: DragEvent<HTMLElement>) => void;
	onEntryDrop?: (entry: FileTreeFileStat, event: DragEvent<HTMLElement>) => void;
	onNavigate?: (path: string) => void;
	onSelectionChange?: (path?: string) => void;
	rootPath?: string;
	isEntryDraggable?: boolean | ((entry: FileTreeFileStat) => boolean);
	renderIcon?: (
		entry: FileTreeFileStat,
		state: { isCurrent: boolean; isOpen: boolean; isSelected: boolean },
	) => ReactNode;
	renderLabel?: (
		entry: FileTreeFileStat,
		state: { isCurrent: boolean; isOpen: boolean; isSelected: boolean },
	) => ReactNode;
	rowHeight?: number;
	selectedPath?: string;
	store?: FileTreeStore;
};

import type Emittery from 'emittery';

export const FileTreeEventType = {
	AbortRequested: 'FileTree:AbortRequested',
	LoadRequested: 'FileTree:LoadRequested',
	NavigateRequested: 'FileTree:NavigateRequested',
	RefreshRequested: 'FileTree:RefreshRequested',
	RevealRequested: 'FileTree:RevealRequested',
	SelectionRequested: 'FileTree:SelectionRequested',
} as const;

export type FileTreeLoadReason = 'expand' | 'retry' | 'reveal' | 'root';

export type FileTreeEventData = {
	[FileTreeEventType.AbortRequested]: { generation: number; path?: string };
	[FileTreeEventType.LoadRequested]: { generation: number; path: string; reason: FileTreeLoadReason };
	[FileTreeEventType.NavigateRequested]: { path: string };
	[FileTreeEventType.RefreshRequested]: { generation: number };
	[FileTreeEventType.RevealRequested]: { generation: number; path: string };
	[FileTreeEventType.SelectionRequested]: { path?: string };
};

export type FileTreeEmitter = Emittery<FileTreeEventData>;

export function normalizeFileTreePath(path: string): string {
	const parts: string[] = [];
	for (const part of String(path).replaceAll('\\', '/').split('/')) {
		if (!part || part === '.') continue;
		if (part === '..') {
			parts.pop();
			continue;
		}
		parts.push(part);
	}
	return `/${parts.join('/')}`;
}

export function isFileTreePathWithinRoot(path: string, rootPath: string): boolean {
	const normalizedPath = normalizeFileTreePath(path);
	const normalizedRoot = normalizeFileTreePath(rootPath);
	return normalizedRoot === '/' || normalizedPath === normalizedRoot || normalizedPath.startsWith(`${normalizedRoot}/`);
}

export function isFileTreePathAtOrBelow(path: string, ancestor: string): boolean {
	const normalizedPath = normalizeFileTreePath(path);
	const normalizedAncestor = normalizeFileTreePath(ancestor);
	return normalizedPath === normalizedAncestor || normalizedPath.startsWith(`${normalizedAncestor}/`);
}

export function getFileTreeParentPath(path: string): string {
	const normalized = normalizeFileTreePath(path);
	if (normalized === '/') return '/';
	const separator = normalized.lastIndexOf('/');
	return separator <= 0 ? '/' : normalized.slice(0, separator);
}

export function getFileTreeBasename(path: string): string {
	const normalized = normalizeFileTreePath(path);
	return normalized === '/' ? '' : normalized.slice(normalized.lastIndexOf('/') + 1);
}

export function validateFileTreeName(name: unknown): name is string {
	return (
		typeof name === 'string' &&
		name.length > 0 &&
		name !== '.' &&
		name !== '..' &&
		!name.includes('/') &&
		!name.includes('\\') &&
		!name.includes('\0')
	);
}

export function joinFileTreePath(directory: string, name: string): string {
	if (!validateFileTreeName(name)) throw new Error(`Invalid direct-child name: ${String(name)}`);
	const normalized = normalizeFileTreePath(directory);
	return normalized === '/' ? `/${name}` : `${normalized}/${name}`;
}

export function getFileTreeDepth(path: string, rootPath: string): number | undefined {
	const normalizedPath = normalizeFileTreePath(path);
	const normalizedRoot = normalizeFileTreePath(rootPath);
	if (!isFileTreePathWithinRoot(normalizedPath, normalizedRoot)) return undefined;
	if (normalizedPath === normalizedRoot) return 0;
	return normalizedPath.slice(normalizedRoot === '/' ? 1 : normalizedRoot.length + 1).split('/').length;
}

export function getFileTreeAncestorPaths(path: string, rootPath: string): string[] {
	const normalizedPath = normalizeFileTreePath(path);
	const normalizedRoot = normalizeFileTreePath(rootPath);
	if (!isFileTreePathWithinRoot(normalizedPath, normalizedRoot)) return [];
	const paths = [normalizedRoot];
	if (normalizedPath === normalizedRoot) return paths;
	const relative = normalizedPath.slice(normalizedRoot === '/' ? 1 : normalizedRoot.length + 1);
	let current = normalizedRoot;
	for (const part of relative.split('/')) {
		current = joinFileTreePath(current, part);
		paths.push(current);
	}
	return paths;
}

import {
	getFileTreeDepth,
	isFileTreePathWithinRoot,
	joinFileTreePath,
	normalizeFileTreePath,
	validateFileTreeName,
} from './file-tree-path';
import type {
	FileTreeDirectoryState,
	FileTreeFileStat,
	FileTreeLimitOptions,
	FileTreeLimits,
	FileTreeMessages,
	FileTreeRenderNode,
	FileTreeStoreState,
} from './file-tree-types';

export const defaultFileTreeLimits: FileTreeLimits = {
	maxCachedDirectories: 256,
	maxConcurrency: 4,
	maxDepth: 64,
	maxNodes: 10_000,
};

export const defaultFileTreeMessages: FileTreeMessages = {
	collapse: '折叠目录',
	empty: '此目录为空',
	expand: '展开目录',
	loadError: (path, error) => `无法读取 ${path}：${error}`,
	loading: '正在加载文件树',
	maxCachedDirectories: '目录缓存已达到上限',
	maxDepth: '已达到目录深度上限',
	maxNodes: '文件树节点数量已达到上限',
	retry: '重试加载',
	treeLabel: '文件树',
};

export function normalizeFileTreeLimits(limits: FileTreeLimitOptions = {}): FileTreeLimits {
	return {
		maxCachedDirectories: normalizeLimit(limits.maxCachedDirectories, defaultFileTreeLimits.maxCachedDirectories),
		maxConcurrency: normalizeLimit(limits.maxConcurrency, defaultFileTreeLimits.maxConcurrency),
		maxDepth: normalizeLimit(limits.maxDepth, defaultFileTreeLimits.maxDepth),
		maxNodes: normalizeLimit(limits.maxNodes, defaultFileTreeLimits.maxNodes),
	};
}

export function resolveFileTreeMessages(messages: Partial<FileTreeMessages> = {}): FileTreeMessages {
	const resolved = { ...defaultFileTreeMessages };
	for (const key of Object.keys(messages) as Array<keyof FileTreeMessages>) {
		const value = messages[key];
		if (value !== undefined) Object.assign(resolved, { [key]: value });
	}
	return resolved;
}

export function sanitizeFileTreeEntries(
	entries: readonly FileTreeFileStat[],
	directory: string,
	rootPath: string,
	directoriesOnly = false,
): FileTreeFileStat[] {
	if (!Array.isArray(entries)) throw new Error('File system returned a non-array directory listing');
	const normalizedDirectory = normalizeFileTreePath(directory);
	const normalizedRoot = normalizeFileTreePath(rootPath);
	if (!isFileTreePathWithinRoot(normalizedDirectory, normalizedRoot))
		throw new Error('Directory escapes the tree root');
	const names = new Set<string>();
	const sanitized: FileTreeFileStat[] = [];
	for (const candidate of entries as readonly unknown[]) {
		if (!isRecord(candidate) || !validateFileTreeName(candidate.name)) {
			throw new Error(
				`File system returned an invalid direct child: ${String(isRecord(candidate) ? candidate.name : '')}`,
			);
		}
		if (names.has(candidate.name)) throw new Error(`File system returned a duplicate direct child: ${candidate.name}`);
		names.add(candidate.name);
		if (candidate.kind !== 'directory' && candidate.kind !== 'file') {
			throw new Error(`File system returned an invalid child kind: ${candidate.name}`);
		}
		const path = joinFileTreePath(normalizedDirectory, candidate.name);
		if (!isFileTreePathWithinRoot(path, normalizedRoot))
			throw new Error(`File system child escapes root: ${candidate.name}`);
		if (directoriesOnly && candidate.kind === 'file') continue;
		sanitized.push({
			directory: normalizedDirectory,
			kind: candidate.kind,
			meta: isRecord(candidate.meta) ? candidate.meta : {},
			mtime: finiteNonNegative(candidate.mtime),
			name: candidate.name,
			path,
			size: finiteNonNegative(candidate.size),
		});
	}
	return sanitized.sort(compareEntries);
}

export function buildFileTreeData(state: FileTreeStoreState): FileTreeRenderNode[] {
	const rootDirectory = state.tree.directories.get(state.source.rootPath);
	if (!isRenderableDirectory(rootDirectory)) return [];
	const roots = createRenderNodes(rootDirectory.entries, 1, state);
	const stack = roots
		.filter((node) => node.kind === 'directory')
		.map((node) => ({ node, depth: 1 }))
		.reverse();
	let visited = roots.length;
	while (stack.length && visited < state.limits.maxNodes) {
		const { node, depth } = stack.pop() as { node: FileTreeRenderNode; depth: number };
		if (depth >= state.limits.maxDepth || !state.tree.expanded.has(node.path)) continue;
		const directory = state.tree.directories.get(node.path);
		if (!isRenderableDirectory(directory)) continue;
		const children = createRenderNodes(directory.entries, depth + 1, state);
		node.children = children;
		visited += children.length;
		for (let index = children.length - 1; index >= 0; index -= 1) {
			const child = children[index];
			if (child.kind === 'directory') stack.push({ node: child, depth: depth + 1 });
		}
	}
	return roots;
}

function isRenderableDirectory(directory: FileTreeDirectoryState | undefined): directory is FileTreeDirectoryState {
	return Boolean(
		directory &&
		(directory.status === 'ready' ||
			((directory.status === 'idle' || directory.status === 'loading' || directory.status === 'queued') &&
				directory.entries.length > 0)),
	);
}

export function flattenFileTreeData(nodes: readonly FileTreeRenderNode[]): FileTreeRenderNode[] {
	const flattened: FileTreeRenderNode[] = [];
	const stack = [...nodes].reverse();
	while (stack.length) {
		const node = stack.pop() as FileTreeRenderNode;
		flattened.push(node);
		if (!node.children) continue;
		for (let index = node.children.length - 1; index >= 0; index -= 1) stack.push(node.children[index]);
	}
	return flattened;
}

export function formatFileTreeDirectoryError(
	directory: { error?: string; errorCode?: string; path: string },
	messages: FileTreeMessages,
): string {
	if (directory.errorCode === 'max-cached-directories') return messages.maxCachedDirectories;
	if (directory.errorCode === 'max-nodes') return messages.maxNodes;
	return messages.loadError(directory.path, directory.error ?? 'Unknown error');
}

function createRenderNodes(
	entries: readonly FileTreeFileStat[],
	depth: number,
	state: FileTreeStoreState,
): FileTreeRenderNode[] {
	return entries.map((entry) => {
		const directory = entry.kind === 'directory' ? state.tree.directories.get(entry.path) : undefined;
		return {
			children: entry.kind === 'directory' && depth < state.limits.maxDepth ? [] : undefined,
			depth,
			entry,
			error: directory?.error,
			errorCode: directory?.errorCode,
			id: entry.path,
			isCurrent: entry.path === state.navigation.currentPath,
			kind: entry.kind,
			name: entry.name,
			path: entry.path,
			status: directory?.status ?? 'idle',
		};
	});
}

function normalizeLimit(value: number | undefined, maximum: number) {
	if (!Number.isFinite(value)) return maximum;
	return Math.max(1, Math.min(Math.floor(value as number), maximum));
}

function finiteNonNegative(value: unknown) {
	return typeof value === 'number' && Number.isFinite(value) && value > 0 ? value : 0;
}

function compareEntries(left: FileTreeFileStat, right: FileTreeFileStat) {
	if (left.kind !== right.kind) return left.kind === 'directory' ? -1 : 1;
	return left.name.localeCompare(right.name, undefined, { numeric: true, sensitivity: 'base' });
}

function isRecord(value: unknown): value is Record<string, unknown> {
	return Boolean(value) && typeof value === 'object' && !Array.isArray(value);
}

export function canLoadFileTreeDirectory(path: string, rootPath: string, limits: FileTreeLimits) {
	const depth = getFileTreeDepth(path, rootPath);
	return depth !== undefined && depth < limits.maxDepth;
}

import Emittery from 'emittery';
import { createStore } from 'zustand/vanilla';
import { mutative } from 'zustand-mutative';
import { type FileTreeEventData, FileTreeEventType } from './file-tree-events';
import { canLoadFileTreeDirectory, normalizeFileTreeLimits } from './file-tree-model';
import {
	getFileTreeAncestorPaths,
	isFileTreePathAtOrBelow,
	isFileTreePathWithinRoot,
	normalizeFileTreePath,
} from './file-tree-path';
import type {
	CreateFileTreeStoreOptions,
	FileTreeActions,
	FileTreeDirectoryState,
	FileTreeSourceOptions,
	FileTreeStoreState,
} from './file-tree-types';

export function createFileTreeStore(options: CreateFileTreeStoreOptions) {
	const rootPath = normalizeFileTreePath(options.rootPath ?? '/');
	const limits = normalizeFileTreeLimits(options.limits);
	const currentPath = normalizeWithin(options.currentPath, rootPath) ?? rootPath;
	const selectedPath = normalizeWithin(options.selectedPath, rootPath);
	const events = new Emittery<FileTreeEventData>();

	return createStore(
		mutative<FileTreeStoreState>((setState, getState) => {
			const defaultActions: FileTreeActions = {
				beginLoad: (requestedPath, generation) => {
					const path = normalizeFileTreePath(requestedPath);
					const state = getState();
					if (generation !== state.source.generation || !isLoadablePath(path, state)) return undefined;
					const existing = state.tree.directories.get(path);
					if (existing?.status === 'ready' || existing?.status === 'loading') return undefined;
					let requestId = 0;
					setState((draft) => {
						draft.requests.nextId += 1;
						requestId = draft.requests.nextId;
						const directory = getOrCreateDirectory(draft, path);
						directory.status = 'loading';
						directory.requestId = requestId;
						directory.error = undefined;
						directory.errorCode = undefined;
						touchState(draft, path);
					});
					return requestId;
				},
				beginRefresh: (requestedPaths, requestedRemovedPaths, generation) => {
					const state = getState();
					if (generation !== state.source.generation) return undefined;
					const removedPaths = normalizeRemovedPaths(requestedRemovedPaths, state);
					if (new Set([...state.tree.pendingRemoval, ...removedPaths]).size > state.limits.maxNodes) {
						setState((draft) => {
							for (const path of draft.tree.directories.keys()) {
								if (path !== draft.source.rootPath) draft.tree.directories.delete(path);
							}
							const root = getOrCreateDirectory(draft, draft.source.rootPath);
							root.status = 'idle';
							root.requestId = undefined;
							root.error = undefined;
							root.errorCode = undefined;
							draft.tree.expanded.clear();
							draft.tree.pendingRefresh.clear();
							draft.tree.pendingRefresh.add(draft.source.rootPath);
							draft.tree.pendingRemoval.clear();
							touchState(draft, draft.source.rootPath);
						});
						return { paths: [state.source.rootPath], removedPaths: [] };
					}
					const blockedPaths = [...state.tree.pendingRemoval, ...removedPaths];
					const paths = normalizeRefreshPaths(requestedPaths, state).filter(
						(path) => !blockedPaths.some((removedPath) => isFileTreePathAtOrBelow(path, removedPath)),
					);
					if (!paths.length && !removedPaths.length) return undefined;
					setState((draft) => {
						for (const removedPath of removedPaths) {
							for (const path of draft.tree.directories.keys()) {
								if (isFileTreePathAtOrBelow(path, removedPath)) draft.tree.directories.delete(path);
							}
							for (const path of draft.tree.expanded) {
								if (isFileTreePathAtOrBelow(path, removedPath)) draft.tree.expanded.delete(path);
							}
							for (const path of draft.tree.pendingRefresh) {
								if (isFileTreePathAtOrBelow(path, removedPath)) draft.tree.pendingRefresh.delete(path);
							}
							draft.tree.pendingRemoval.add(removedPath);
						}
						for (const path of paths) {
							const directory = draft.tree.directories.get(path);
							if (!directory) continue;
							directory.status = 'idle';
							directory.requestId = undefined;
							directory.error = undefined;
							directory.errorCode = undefined;
							draft.tree.pendingRefresh.add(path);
							touchState(draft, path);
						}
					});
					return { paths, removedPaths };
				},
				beginReveal: (requestedPath, generation) => {
					const path = normalizeFileTreePath(requestedPath);
					const state = getState();
					if (generation !== state.source.generation || !isFileTreePathWithinRoot(path, state.source.rootPath))
						return false;
					setState((draft) => {
						draft.reveal = { path, status: 'loading' };
						touchState(draft, path);
					});
					return true;
				},
				cancelLoad: (requestedPath, generation, requestId) => {
					const path = normalizeFileTreePath(requestedPath);
					const state = getState();
					const directory = state.tree.directories.get(path);
					if (
						generation !== state.source.generation ||
						!directory ||
						(requestId !== undefined && directory.requestId !== requestId) ||
						(directory.status !== 'loading' && directory.status !== 'queued')
					)
						return false;
					setState((draft) => {
						const next = draft.tree.directories.get(path);
						if (!next) return;
						next.status = 'idle';
						next.requestId = undefined;
					});
					return true;
				},
				collapse: (requestedPath) => {
					const path = normalizeFileTreePath(requestedPath);
					const state = getState();
					if (!isFileTreePathWithinRoot(path, state.source.rootPath)) return;
					setState((draft) => {
						for (const expanded of draft.tree.expanded) {
							if (isFileTreePathAtOrBelow(expanded, path)) draft.tree.expanded.delete(expanded);
						}
						touchState(draft, path);
					});
					void events.emit(FileTreeEventType.AbortRequested, { generation: state.source.generation, path });
				},
				completeLoad: (requestedPath, generation, requestId, entries) => {
					const path = normalizeFileTreePath(requestedPath);
					const state = getState();
					const directory = state.tree.directories.get(path);
					if (
						generation !== state.source.generation ||
						directory?.status !== 'loading' ||
						directory.requestId !== requestId
					)
						return false;
					setState((draft) => {
						const next = getOrCreateDirectory(draft, path);
						next.entries = entries;
						next.status = 'ready';
						next.requestId = undefined;
						next.error = undefined;
						next.errorCode = undefined;
						touchState(draft, path);
						const limitError = enforceCacheLimits(draft, path);
						if (limitError) {
							const failed = getOrCreateDirectory(draft, path);
							failed.entries = [];
							failed.status = 'error';
							failed.errorCode = limitError;
							failed.error = limitError;
						}
					});
					return true;
				},
				completeReveal: (requestedPath, generation) =>
					settleReveal(setState, getState, requestedPath, generation, undefined),
				consumeRefresh: (generation) => {
					const state = getState();
					if (generation !== state.source.generation) return undefined;
					const paths = [...state.tree.pendingRefresh];
					const removedPaths = [...state.tree.pendingRemoval];
					if (!paths.length && !removedPaths.length) return undefined;
					setState((draft) => {
						draft.tree.pendingRefresh.clear();
						draft.tree.pendingRemoval.clear();
					});
					return { paths, removedPaths };
				},
				expand: (requestedPath) => {
					const path = normalizeFileTreePath(requestedPath);
					const state = getState();
					if (!isLoadablePath(path, state)) return;
					setState((draft) => {
						draft.tree.expanded.add(path);
						touchState(draft, path);
					});
					getState().actions.requestLoad(path, 'expand');
				},
				failLoad: (requestedPath, generation, requestId, error, errorCode = 'load') => {
					const path = normalizeFileTreePath(requestedPath);
					const state = getState();
					const directory = state.tree.directories.get(path);
					if (
						generation !== state.source.generation ||
						directory?.status !== 'loading' ||
						directory.requestId !== requestId
					)
						return false;
					setState((draft) => {
						const next = getOrCreateDirectory(draft, path);
						next.status = 'error';
						next.requestId = undefined;
						next.error = error;
						next.errorCode = errorCode;
					});
					return true;
				},
				failReveal: (requestedPath, generation, error) =>
					settleReveal(setState, getState, requestedPath, generation, error),
				replaceSource: (nextOptions) => {
					const state = getState();
					const nextRoot = normalizeFileTreePath(nextOptions.rootPath ?? '/');
					const nextLimits = normalizeFileTreeLimits(nextOptions.limits);
					const nextDirectoriesOnly = nextOptions.directoriesOnly ?? false;
					if (
						state.source.fileSystem === nextOptions.fileSystem &&
						state.source.rootPath === nextRoot &&
						state.source.directoriesOnly === nextDirectoriesOnly &&
						limitsEqual(state.limits, nextLimits)
					)
						return false;
					const previousGeneration = state.source.generation;
					const generation = previousGeneration + 1;
					setState((draft) => {
						draft.source = {
							directoriesOnly: nextDirectoriesOnly,
							fileSystem: nextOptions.fileSystem,
							generation,
							rootPath: nextRoot,
						};
						draft.limits = nextLimits;
						draft.tree = {
							clock: 0,
							directories: new Map([[nextRoot, createDirectory(nextRoot)]]),
							expanded: new Set(),
							pendingRefresh: new Set(),
							pendingRemoval: new Set(),
						};
						draft.navigation.currentPath = normalizeWithin(draft.navigation.currentPath, nextRoot) ?? nextRoot;
						draft.selection.path = normalizeWithin(draft.selection.path, nextRoot);
						draft.reveal = { status: 'idle' };
					});
					void events.emit(FileTreeEventType.AbortRequested, { generation: previousGeneration });
					return true;
				},
				requestLoad: (requestedPath, reason = 'expand') => {
					const path = normalizeFileTreePath(requestedPath);
					const state = getState();
					if (!isLoadablePath(path, state)) return;
					const directory = state.tree.directories.get(path);
					if (directory?.status === 'ready' || directory?.status === 'loading' || directory?.status === 'queued') {
						if (directory.status === 'ready') getState().actions.touch(path);
						return;
					}
					setState((draft) => {
						const next = getOrCreateDirectory(draft, path);
						next.status = 'queued';
						next.error = undefined;
						next.errorCode = undefined;
						touchState(draft, path);
					});
					void events.emit(FileTreeEventType.LoadRequested, {
						generation: state.source.generation,
						path,
						reason,
					});
				},
				requestNavigate: (requestedPath) => {
					const path = normalizeWithin(requestedPath, getState().source.rootPath);
					if (path) void events.emit(FileTreeEventType.NavigateRequested, { path });
				},
				requestRefresh: (requestedPaths, options = {}) => {
					const state = getState();
					const paths = normalizeRefreshPaths(requestedPaths, state);
					const removedPaths = normalizeRemovedPaths(options.removedPaths ?? [], state);
					if (!paths.length && !removedPaths.length) return;
					if (!getState().actions.beginRefresh(paths, removedPaths, state.source.generation)) return;
					void events.emit(FileTreeEventType.RefreshRequested, { generation: state.source.generation });
				},
				requestReveal: (requestedPath) => {
					const path = normalizeWithin(requestedPath, getState().source.rootPath);
					if (!path) return;
					const generation = getState().source.generation;
					void events.emit(FileTreeEventType.RevealRequested, { generation, path });
				},
				requestSelection: (requestedPath) => {
					const path = normalizeWithin(requestedPath, getState().source.rootPath);
					void events.emit(FileTreeEventType.SelectionRequested, { path });
				},
				retry: (requestedPath) => {
					const path = normalizeFileTreePath(requestedPath);
					const directory = getState().tree.directories.get(path);
					if (directory?.status !== 'error') return;
					setState((draft) => {
						const next = draft.tree.directories.get(path);
						if (next) next.status = 'idle';
					});
					getState().actions.requestLoad(path, 'retry');
				},
				syncCurrentPath: (requestedPath) => {
					const state = getState();
					const path = normalizeWithin(requestedPath, state.source.rootPath) ?? state.source.rootPath;
					if (state.navigation.currentPath === path) return;
					setState((draft) => {
						draft.navigation.currentPath = path;
						touchState(draft, path);
					});
					getState().actions.requestReveal(path);
				},
				syncSelectedPath: (requestedPath) => {
					const path = normalizeWithin(requestedPath, getState().source.rootPath);
					if (getState().selection.path === path) return;
					setState((draft) => {
						draft.selection.path = path;
						if (path) touchState(draft, path);
					});
				},
				toggle: (path) => {
					const state = getState();
					if (state.tree.expanded.has(normalizeFileTreePath(path))) state.actions.collapse(path);
					else state.actions.expand(path);
				},
				touch: (requestedPath) => {
					const path = normalizeFileTreePath(requestedPath);
					if (!isFileTreePathWithinRoot(path, getState().source.rootPath)) return;
					setState((draft) => touchState(draft, path));
				},
			};

			return {
				source: {
					directoriesOnly: options.directoriesOnly ?? false,
					fileSystem: options.fileSystem,
					generation: 1,
					rootPath,
				},
				limits,
				tree: {
					clock: 0,
					directories: new Map([[rootPath, createDirectory(rootPath)]]),
					expanded: new Set(),
					pendingRefresh: new Set(),
					pendingRemoval: new Set(),
				},
				selection: { path: selectedPath },
				navigation: { currentPath },
				reveal: { status: 'idle' },
				requests: { nextId: 0 },
				events,
				actions: { ...defaultActions, ...options.actions },
			};
		}),
	);
}

function settleReveal(
	setState: Parameters<Parameters<typeof mutative<FileTreeStoreState>>[0]>[0],
	getState: () => FileTreeStoreState,
	requestedPath: string,
	generation: number,
	error?: string,
) {
	const path = normalizeFileTreePath(requestedPath);
	const state = getState();
	if (generation !== state.source.generation || state.reveal.path !== path || state.reveal.status !== 'loading')
		return false;
	setState((draft) => {
		draft.reveal = error ? { error, path, status: 'error' } : { path, status: 'ready' };
	});
	return true;
}

function enforceCacheLimits(state: FileTreeStoreState, committingPath: string) {
	const protectedPaths = getProtectedPaths(state);
	const candidates = [...state.tree.directories.values()]
		.filter((directory) => directory.status === 'ready' && !protectedPaths.has(directory.path))
		.sort((left, right) => left.lastAccess - right.lastAccess);
	let cachedDirectories = countReadyDirectories(state);
	let nodes = countCachedNodes(state);
	while (
		candidates.length &&
		(cachedDirectories > state.limits.maxCachedDirectories || nodes > state.limits.maxNodes)
	) {
		const candidate = candidates.shift() as FileTreeDirectoryState;
		if (candidate.path === committingPath && protectedPaths.has(committingPath)) continue;
		state.tree.directories.delete(candidate.path);
		cachedDirectories -= 1;
		nodes -= candidate.entries.length;
	}
	if (nodes > state.limits.maxNodes) return 'max-nodes' as const;
	if (cachedDirectories > state.limits.maxCachedDirectories) return 'max-cached-directories' as const;
	return undefined;
}

function getProtectedPaths(state: FileTreeStoreState) {
	const protectedPaths = new Set<string>([state.source.rootPath]);
	const sources = [state.navigation.currentPath, state.selection.path, ...state.tree.expanded];
	for (const directory of state.tree.directories.values()) {
		if (directory.status === 'loading' || directory.status === 'queued') sources.push(directory.path);
	}
	for (const path of sources) {
		if (!path) continue;
		for (const ancestor of getFileTreeAncestorPaths(path, state.source.rootPath)) protectedPaths.add(ancestor);
	}
	return protectedPaths;
}

function countReadyDirectories(state: FileTreeStoreState) {
	let count = 0;
	for (const directory of state.tree.directories.values()) if (directory.status === 'ready') count += 1;
	return count;
}

function countCachedNodes(state: FileTreeStoreState) {
	let count = 0;
	for (const directory of state.tree.directories.values()) {
		if (directory.status === 'ready') count += directory.entries.length;
	}
	return count;
}

function touchState(state: FileTreeStoreState, path: string) {
	state.tree.clock += 1;
	for (const ancestor of getFileTreeAncestorPaths(path, state.source.rootPath)) {
		const directory = state.tree.directories.get(ancestor);
		if (directory) directory.lastAccess = state.tree.clock;
	}
}

function getOrCreateDirectory(state: FileTreeStoreState, path: string) {
	let directory = state.tree.directories.get(path);
	if (!directory) {
		directory = createDirectory(path);
		state.tree.directories.set(path, directory);
	}
	return directory;
}

function createDirectory(path: string): FileTreeDirectoryState {
	return { entries: [], lastAccess: 0, path, status: 'idle' };
}

function isLoadablePath(path: string, state: FileTreeStoreState) {
	return (
		isFileTreePathWithinRoot(path, state.source.rootPath) &&
		canLoadFileTreeDirectory(path, state.source.rootPath, state.limits)
	);
}

function normalizeWithin(path: string | undefined, rootPath: string) {
	if (path === undefined) return undefined;
	const normalized = normalizeFileTreePath(path);
	return isFileTreePathWithinRoot(normalized, rootPath) ? normalized : undefined;
}

function normalizeRefreshPaths(requestedPaths: readonly string[], state: FileTreeStoreState) {
	const paths = new Set<string>();
	const limit = Math.min(requestedPaths.length, state.limits.maxNodes);
	for (let index = 0; index < limit; index += 1) {
		const requestedPath = requestedPaths[index];
		if (typeof requestedPath !== 'string') continue;
		const path = normalizeFileTreePath(requestedPath);
		if (!isLoadablePath(path, state) || !state.tree.directories.has(path)) continue;
		paths.add(path);
	}
	return [...paths];
}

function normalizeRemovedPaths(requestedPaths: readonly string[], state: FileTreeStoreState) {
	const paths = new Set<string>();
	const limit = Math.min(requestedPaths.length, state.limits.maxNodes);
	for (let index = 0; index < limit; index += 1) {
		const requestedPath = requestedPaths[index];
		if (typeof requestedPath !== 'string') continue;
		const path = normalizeFileTreePath(requestedPath);
		if (path === state.source.rootPath || !isFileTreePathWithinRoot(path, state.source.rootPath)) continue;
		paths.add(path);
	}
	return [...paths];
}

function limitsEqual(left: FileTreeStoreState['limits'], right: FileTreeStoreState['limits']) {
	return (
		left.maxCachedDirectories === right.maxCachedDirectories &&
		left.maxConcurrency === right.maxConcurrency &&
		left.maxDepth === right.maxDepth &&
		left.maxNodes === right.maxNodes
	);
}

export type { FileTreeSourceOptions };

'use client';

import { createContext, type PropsWithChildren, useContext, useState } from 'react';
import { useStore } from 'zustand';
import { useShallow } from 'zustand/react/shallow';
import { createFileTreeStore } from './file-tree-store';
import type { CreateFileTreeStoreOptions, FileTreeActions, FileTreeStore, FileTreeStoreState } from './file-tree-types';

export const FileTreeContext = createContext<FileTreeStore | null>(null);

export type FileTreeProviderProps = PropsWithChildren<{
	options?: CreateFileTreeStoreOptions;
	store?: FileTreeStore;
}>;

export function FileTreeProvider({ children, options, store }: FileTreeProviderProps) {
	const parentStore = useContext(FileTreeContext);
	const [localStore] = useState(() => {
		if (store) return store;
		if (options) return createFileTreeStore(options);
		if (parentStore) return parentStore;
		throw new Error('FileTreeProvider requires options or store');
	});
	return <FileTreeContext.Provider value={store ?? localStore}>{children}</FileTreeContext.Provider>;
}

export function useFileTreeStoreContext(): FileTreeStore {
	const store = useContext(FileTreeContext);
	if (!store) throw new Error('useFileTreeStore must be used within FileTreeProvider');
	return store;
}

export function useFileTreeStore<T>(selector: (state: FileTreeStoreState) => T): T {
	return useStore(useFileTreeStoreContext(), selector);
}

export function useFileTreeActions(): FileTreeActions {
	return useFileTreeStore((state) => state.actions);
}

export function useFileTreeViewState() {
	return useFileTreeStore(
		useShallow((state) => ({
			actions: state.actions,
			currentPath: state.navigation.currentPath,
			directories: state.tree.directories,
			expanded: state.tree.expanded,
			limits: state.limits,
			rootPath: state.source.rootPath,
			selectedPath: state.selection.path,
		})),
	);
}

import { FileTreeEventType } from './file-tree-events';
import { sanitizeFileTreeEntries } from './file-tree-model';
import { getFileTreeAncestorPaths, isFileTreePathAtOrBelow, normalizeFileTreePath } from './file-tree-path';
import type { FileTreeStore } from './file-tree-types';

export type FileTreeRuntime = {
	dispose: () => void;
	start: () => void;
	whenIdle: () => Promise<void>;
};

type LoadJob = {
	cancelled: boolean;
	controller?: AbortController;
	generation: number;
	path: string;
	promise: Promise<void>;
	requestId?: number;
	resolve: () => void;
};

export function createFileTreeRuntime(store: FileTreeStore): FileTreeRuntime {
	const jobs = new Map<string, LoadJob>();
	const queue: LoadJob[] = [];
	const reveals = new Map<string, Promise<void>>();
	const idleWaiters = new Set<() => void>();
	let active = 0;
	let disposed = false;
	let started = false;
	let unsubscribe: Array<() => void> = [];

	const ensureLoad = (requestedPath: string, generation: number) => {
		const path = normalizeFileTreePath(requestedPath);
		const state = store.getState();
		if (generation !== state.source.generation) return Promise.resolve();
		if (state.tree.directories.get(path)?.status === 'ready') {
			state.actions.touch(path);
			return Promise.resolve();
		}
		const existing = jobs.get(path);
		if (existing?.generation === generation && !existing.cancelled) return existing.promise;
		let resolve: () => void = () => undefined;
		const promise = new Promise<void>((done) => {
			resolve = done;
		});
		const job: LoadJob = { cancelled: false, generation, path, promise, resolve };
		jobs.set(path, job);
		queue.push(job);
		pump();
		return promise;
	};

	const reveal = (requestedPath: string, generation: number) => {
		const target = normalizeFileTreePath(requestedPath);
		const key = `${generation}:${target}`;
		const existing = reveals.get(key);
		if (existing) return existing;
		const promise = runReveal(target, generation).finally(() => {
			reveals.delete(key);
			notifyIdle();
		});
		reveals.set(key, promise);
		return promise;
	};
	const drainRefresh = (generation: number) => {
		const pending = store.getState().actions.consumeRefresh(generation);
		if (!pending) return;
		for (const path of pending.removedPaths) abortJobs(path, generation);
		for (const path of pending.paths) abortJobs(path, generation, false);
		for (const path of pending.paths) void ensureLoad(path, generation);
	};

	function start() {
		if (started || disposed) return;
		started = true;
		const events = store.getState().events;
		unsubscribe = [
			events.on(FileTreeEventType.LoadRequested, ({ data }) => {
				void ensureLoad(data.path, data.generation);
			}),
			events.on(FileTreeEventType.RevealRequested, ({ data }) => {
				void reveal(data.path, data.generation);
			}),
			events.on(FileTreeEventType.RefreshRequested, ({ data }) => {
				drainRefresh(data.generation);
			}),
			events.on(FileTreeEventType.AbortRequested, ({ data }) => {
				abortJobs(data.path, data.generation);
			}),
		];
		const state = store.getState();
		drainRefresh(state.source.generation);
		void ensureLoad(state.source.rootPath, state.source.generation);
		void reveal(state.navigation.currentPath, state.source.generation);
	}

	function dispose() {
		if (disposed) return;
		disposed = true;
		for (const off of unsubscribe) off();
		unsubscribe = [];
		abortJobs(undefined, store.getState().source.generation, true, true);
		notifyIdle();
	}

	async function whenIdle() {
		await Promise.resolve();
		if (active === 0 && reveals.size === 0 && !queue.some((job) => !job.cancelled)) return;
		await new Promise<void>((resolve) => idleWaiters.add(resolve));
	}

	function pump() {
		if (disposed) return;
		const concurrency = store.getState().limits.maxConcurrency;
		while (active < concurrency && queue.length) {
			const job = queue.shift() as LoadJob;
			if (job.cancelled || jobs.get(job.path) !== job) continue;
			active += 1;
			void runLoad(job);
		}
		notifyIdle();
	}

	async function runLoad(job: LoadJob) {
		const state = store.getState();
		if (disposed || job.cancelled || job.generation !== state.source.generation) {
			finishJob(job);
			return;
		}
		const requestId = state.actions.beginLoad(job.path, job.generation);
		if (requestId === undefined) {
			finishJob(job);
			return;
		}
		job.requestId = requestId;
		const controller = new AbortController();
		job.controller = controller;
		const source = store.getState().source;
		try {
			const entries = await source.fileSystem.readdir(job.path, { signal: controller.signal });
			if (disposed || job.cancelled || controller.signal.aborted) {
				store.getState().actions.cancelLoad(job.path, job.generation, requestId);
				return;
			}
			const current = store.getState();
			if (current.source.generation !== job.generation || current.source.fileSystem !== source.fileSystem) return;
			if (!Array.isArray(entries)) throw new Error('File system returned a non-array directory listing');
			if (entries.length > current.limits.maxNodes) {
				throw new FileTreeNodeLimitError(current.limits.maxNodes);
			}
			const sanitized = sanitizeFileTreeEntries(
				entries,
				job.path,
				current.source.rootPath,
				current.source.directoriesOnly,
			);
			if (current.actions.completeLoad(job.path, job.generation, requestId, sanitized)) {
				const latest = store.getState();
				if (
					latest.tree.directories.get(job.path)?.status === 'ready' &&
					latest.reveal.status === 'error' &&
					isFileTreePathAtOrBelow(latest.navigation.currentPath, job.path)
				) {
					void reveal(latest.navigation.currentPath, job.generation);
				}
			}
		} catch (error) {
			const current = store.getState();
			if (controller.signal.aborted || job.cancelled || isAbortError(error)) {
				current.actions.cancelLoad(job.path, job.generation, requestId);
			} else {
				current.actions.failLoad(
					job.path,
					job.generation,
					requestId,
					getErrorMessage(error),
					error instanceof FileTreeNodeLimitError ? 'max-nodes' : 'load',
				);
			}
		} finally {
			finishJob(job);
		}
	}

	async function runReveal(target: string, generation: number) {
		const initial = store.getState();
		if (!initial.actions.beginReveal(target, generation)) return;
		const paths = getFileTreeAncestorPaths(target, initial.source.rootPath);
		if (!paths.length || paths.length - 1 > initial.limits.maxDepth) {
			initial.actions.failReveal(target, generation, 'Current path exceeds the tree depth limit');
			return;
		}
		await ensureLoad(paths[0], generation);
		for (let index = 1; index < paths.length; index += 1) {
			const state = store.getState();
			if (
				disposed ||
				state.source.generation !== generation ||
				state.reveal.path !== target ||
				state.reveal.status !== 'loading'
			)
				return;
			const parent = state.tree.directories.get(paths[index - 1]);
			if (parent?.status !== 'ready') {
				state.actions.failReveal(target, generation, `Unable to load ancestor: ${paths[index - 1]}`);
				return;
			}
			const child = parent.entries.find((entry) => entry.path === paths[index]);
			if (!child) {
				state.actions.failReveal(target, generation, `Current path was not found: ${paths[index]}`);
				return;
			}
			if (index === paths.length - 1) break;
			if (child.kind !== 'directory') {
				state.actions.failReveal(target, generation, `Current path crosses a file: ${child.path}`);
				return;
			}
			state.actions.expand(child.path);
			await ensureLoad(child.path, generation);
		}
		store.getState().actions.completeReveal(target, generation);
	}

	function abortJobs(
		requestedPath: string | undefined,
		generation: number,
		includeDescendants = true,
		allGenerations = false,
	) {
		const path = requestedPath ? normalizeFileTreePath(requestedPath) : undefined;
		for (const job of jobs.values()) {
			if (!allGenerations && job.generation !== generation) continue;
			if (path && (includeDescendants ? !isFileTreePathAtOrBelow(job.path, path) : job.path !== path)) continue;
			job.cancelled = true;
			job.controller?.abort();
			store.getState().actions.cancelLoad(job.path, job.generation, job.requestId);
			if (!job.controller) finishQueuedJob(job);
		}
		notifyIdle();
	}

	function finishQueuedJob(job: LoadJob) {
		if (jobs.get(job.path) === job) jobs.delete(job.path);
		job.resolve();
	}

	function finishJob(job: LoadJob) {
		if (jobs.get(job.path) === job) jobs.delete(job.path);
		active = Math.max(0, active - 1);
		job.resolve();
		pump();
	}

	function notifyIdle() {
		if (active !== 0 || reveals.size !== 0 || queue.some((job) => !job.cancelled)) return;
		for (const resolve of idleWaiters) resolve();
		idleWaiters.clear();
	}

	return { dispose, start, whenIdle };
}

class FileTreeNodeLimitError extends Error {
	constructor(limit: number) {
		super(`Directory entry count exceeds the tree node limit: ${limit}`);
		this.name = 'FileTreeNodeLimitError';
	}
}

function isAbortError(error: unknown) {
	return error instanceof DOMException ? error.name === 'AbortError' : getErrorName(error) === 'AbortError';
}

function getErrorName(error: unknown) {
	return error && typeof error === 'object' && 'name' in error ? String(error.name) : '';
}

function getErrorMessage(error: unknown) {
	return error instanceof Error ? error.message : String(error);
}

'use client';

import {
	ChevronDown,
	ChevronRight,
	CircleSlash2,
	File,
	Folder,
	FolderOpen,
	LoaderCircle,
	RotateCcw,
	TriangleAlert,
} from 'lucide-react';
import type { MouseEvent } from 'react';
import type { NodeRendererProps, RowRendererProps } from 'react-arborist';
import { formatFileTreeDirectoryError } from './file-tree-model';
import type { FileTreeDropTarget, FileTreeMessages, FileTreeProps, FileTreeRenderNode } from './file-tree-types';

export function FileTreeRow({ node, attrs, innerRef, children }: RowRendererProps<FileTreeRenderNode>) {
	const handleClick = (event: MouseEvent<HTMLDivElement>) => {
		if ((event.metaKey || event.ctrlKey) && !node.tree.props.disableMultiSelection) {
			if (node.isSelected) node.deselect();
			else node.selectMulti();
		} else if (event.shiftKey && !node.tree.props.disableMultiSelection) {
			node.selectContiguous();
		} else {
			node.select();
		}
	};
	return (
		<div
			{...attrs}
			aria-current={node.data.isCurrent ? 'location' : undefined}
			aria-expanded={node.isInternal ? node.isOpen : undefined}
			ref={innerRef}
			onClick={handleClick}
			onDoubleClick={() => node.activate()}
			onFocus={(event) => event.stopPropagation()}
			onKeyDown={(event) => {
				if (event.key !== 'Enter' || event.target !== event.currentTarget) return;
				event.preventDefault();
				node.activate();
			}}
		>
			{children}
		</div>
	);
}

export type FileTreeNodeProps = NodeRendererProps<FileTreeRenderNode> & {
	dropTarget?: FileTreeDropTarget;
	isEntryDraggable?: FileTreeProps['isEntryDraggable'];
	messages: FileTreeMessages;
	onEntryDragEnd?: FileTreeProps['onEntryDragEnd'];
	onEntryDragLeave?: FileTreeProps['onEntryDragLeave'];
	onEntryDragOver?: FileTreeProps['onEntryDragOver'];
	onEntryDragStart?: FileTreeProps['onEntryDragStart'];
	onEntryDrop?: FileTreeProps['onEntryDrop'];
	onRetry: (path: string) => void;
	renderIcon?: FileTreeProps['renderIcon'];
	renderLabel?: FileTreeProps['renderLabel'];
};

export function FileTreeNode({
	dragHandle,
	dropTarget,
	isEntryDraggable,
	messages,
	node,
	onEntryDragEnd,
	onEntryDragLeave,
	onEntryDragOver,
	onEntryDragStart,
	onEntryDrop,
	onRetry,
	renderIcon,
	renderLabel,
	style,
}: FileTreeNodeProps) {
	const data = node.data;
	const draggable = typeof isEntryDraggable === 'function' ? isEntryDraggable(data.entry) : isEntryDraggable;
	const directoryError = data.status === 'error';
	const activeDropTarget = dropTarget?.path === data.path ? dropTarget : undefined;
	const rejectedDropTarget = activeDropTarget?.state === 'rejected' ? activeDropTarget : undefined;
	const renderState = { isCurrent: data.isCurrent, isOpen: node.isOpen, isSelected: node.isSelected };
	const defaultIcon =
		data.status === 'loading' || data.status === 'queued' ? (
			<LoaderCircle aria-hidden='true' className='text-info size-4 shrink-0 animate-spin' />
		) : data.kind === 'directory' ? (
			node.isOpen ? (
				<FolderOpen aria-hidden='true' className='text-warning size-4 shrink-0' />
			) : (
				<Folder aria-hidden='true' className='text-warning size-4 shrink-0' />
			)
		) : (
			<File aria-hidden='true' className='text-base-content/60 size-4 shrink-0' />
		);
	return (
		<div
			ref={dragHandle}
			style={style}
			className='hover:bg-base-200 data-[current=true]:bg-info/15 data-[current=true]:text-base-content data-[drop-state=accepted]:bg-info/20 data-[drop-state=accepted]:ring-info data-[drop-state=rejected]:bg-error/10 data-[drop-state=rejected]:text-base-content/45 data-[drop-state=rejected]:ring-error/60 flex h-full min-w-max items-center gap-1 px-1 text-sm data-[current=true]:font-medium data-[drop-state=accepted]:ring-1 data-[drop-state=accepted]:ring-inset data-[drop-state=rejected]:cursor-not-allowed data-[drop-state=rejected]:ring-1 data-[drop-state=rejected]:ring-inset'
			aria-disabled={rejectedDropTarget ? true : undefined}
			data-current={data.isCurrent || undefined}
			data-drop-state={activeDropTarget?.state}
			data-drop-target={activeDropTarget ? true : undefined}
			data-kind={data.kind}
			data-path={data.path}
			title={rejectedDropTarget?.reason}
			draggable={draggable || undefined}
			onDragEnd={(event) => onEntryDragEnd?.(data.entry, event)}
			onDragLeave={(event) => onEntryDragLeave?.(data.entry, event)}
			onDragOver={(event) => onEntryDragOver?.(data.entry, event)}
			onDragStart={(event) => onEntryDragStart?.(data.entry, event)}
			onDrop={(event) => onEntryDrop?.(data.entry, event)}
		>
			{data.kind === 'directory' && node.isInternal ? (
				<button
					type='button'
					tabIndex={-1}
					className='hover:bg-base-300 inline-flex size-6 shrink-0 items-center justify-center rounded-sm'
					aria-label={node.isOpen ? messages.collapse : messages.expand}
					title={node.isOpen ? messages.collapse : messages.expand}
					onClick={(event) => {
						event.stopPropagation();
						node.toggle();
					}}
					onDoubleClick={(event) => event.stopPropagation()}
				>
					{node.isOpen ? (
						<ChevronDown aria-hidden='true' className='size-4' />
					) : (
						<ChevronRight aria-hidden='true' className='size-4' />
					)}
				</button>
			) : (
				<span
					className='inline-flex size-6 shrink-0'
					title={data.kind === 'directory' ? messages.maxDepth : undefined}
				/>
			)}
			{renderIcon?.(data.entry, renderState) ?? defaultIcon}
			<span className='max-w-80 truncate'>{renderLabel?.(data.entry, renderState) ?? data.name}</span>
			{rejectedDropTarget ? (
				<CircleSlash2 aria-label={rejectedDropTarget.reason} className='text-error ml-1 size-3.5 shrink-0' />
			) : null}
			{directoryError ? (
				<>
					<TriangleAlert
						aria-label={formatFileTreeDirectoryError(data, messages)}
						className='text-error ml-1 size-4 shrink-0'
					/>
					<button
						type='button'
						className='hover:bg-base-300 inline-flex size-6 shrink-0 items-center justify-center rounded-sm'
						aria-label={messages.retry}
						title={messages.retry}
						onClick={(event) => {
							event.stopPropagation();
							onRetry(data.path);
						}}
						onDoubleClick={(event) => event.stopPropagation()}
					>
						<RotateCcw aria-hidden='true' className='size-3.5' />
					</button>
				</>
			) : null}
		</div>
	);
}

'use client';

import { LoaderCircle, RotateCcw, TriangleAlert } from 'lucide-react';
import { type ComponentPropsWithRef, forwardRef, useCallback, useEffect, useMemo, useRef } from 'react';
import { type NodeRendererProps, Tree, type TreeApi } from 'react-arborist';
import { cn } from '@/lib/utils';
import { FileTreeProvider, useFileTreeStore, useFileTreeStoreContext } from './file-tree-context';
import { FileTreeEventType } from './file-tree-events';
import {
	buildFileTreeData,
	formatFileTreeDirectoryError,
	normalizeFileTreeLimits,
	resolveFileTreeMessages,
} from './file-tree-model';
import { normalizeFileTreePath } from './file-tree-path';
import { FileTreeNode, FileTreeRow } from './file-tree-row';
import { createFileTreeRuntime } from './file-tree-runtime';
import type {
	FileTreeDirectoryState,
	FileTreeDropTarget,
	FileTreeFileStat,
	FileTreeFileSystem,
	FileTreeLimits,
	FileTreeMessages,
	FileTreeProps,
	FileTreeRenderNode,
	FileTreeStoreState,
} from './file-tree-types';

export const FileTree = forwardRef<HTMLDivElement, FileTreeProps>(function FileTree(props, ref) {
	const selectedControlled = Object.hasOwn(props, 'selectedPath');
	const currentControlled = Object.hasOwn(props, 'currentPath');
	const {
		['aria-label']: ariaLabel,
		className,
		currentPath,
		defaultCurrentPath,
		defaultSelectedPath,
		directoriesOnly = false,
		dropTarget,
		dropTargetPath,
		fileSystem,
		height: requestedHeight = 320,
		indent: requestedIndent = 20,
		limits: limitOptions,
		messages: messageOptions,
		onActivate,
		onEntryDragEnd,
		onEntryDragLeave,
		onEntryDragOver,
		onEntryDragStart,
		onEntryDrop,
		onNavigate,
		onSelectionChange,
		rootPath = '/',
		isEntryDraggable,
		rowHeight: requestedRowHeight = 30,
		renderIcon,
		renderLabel,
		selectedPath,
		store,
		style,
		...divProps
	} = props;
	const limits = useMemo(
		() => normalizeFileTreeLimits(limitOptions),
		[limitOptions?.maxCachedDirectories, limitOptions?.maxConcurrency, limitOptions?.maxDepth, limitOptions?.maxNodes],
	);
	const messages = useMemo(() => resolveFileTreeMessages(messageOptions), [messageOptions]);
	const normalizedRoot = normalizeFileTreePath(rootPath);
	const height = normalizeSize(requestedHeight, 320, 1, 4_096);
	const indent = normalizeSize(requestedIndent, 20, 8, 64);
	const rowHeight = normalizeSize(requestedRowHeight, 30, 20, 80);
	const resolvedDropTarget = useMemo<FileTreeDropTarget | undefined>(() => {
		if (dropTarget) return { ...dropTarget, path: normalizeFileTreePath(dropTarget.path) };
		if (dropTargetPath) return { path: normalizeFileTreePath(dropTargetPath), state: 'accepted' };
		return undefined;
	}, [dropTarget, dropTargetPath]);

	return (
		<FileTreeProvider
			store={store}
			options={{
				currentPath: currentControlled ? (currentPath ?? normalizedRoot) : (defaultCurrentPath ?? normalizedRoot),
				directoriesOnly,
				fileSystem,
				limits,
				rootPath: normalizedRoot,
				selectedPath: selectedControlled ? selectedPath : defaultSelectedPath,
			}}
		>
			<FileTreeSidecar
				currentControlled={currentControlled}
				currentPath={currentPath}
				directoriesOnly={directoriesOnly}
				fileSystem={fileSystem}
				limits={limits}
				onActivate={onActivate}
				onNavigate={onNavigate}
				onSelectionChange={onSelectionChange}
				rootPath={normalizedRoot}
				selectedControlled={selectedControlled}
				selectedPath={selectedPath}
			/>
			<FileTreeView
				{...divProps}
				ariaLabel={ariaLabel ?? messages.treeLabel}
				className={className}
				dropTarget={resolvedDropTarget}
				height={height}
				indent={indent}
				isEntryDraggable={isEntryDraggable}
				messages={messages}
				onEntryDragEnd={onEntryDragEnd}
				onEntryDragLeave={onEntryDragLeave}
				onEntryDragOver={onEntryDragOver}
				onEntryDragStart={onEntryDragStart}
				onEntryDrop={onEntryDrop}
				ref={ref}
				renderIcon={renderIcon}
				renderLabel={renderLabel}
				rowHeight={rowHeight}
				style={style}
			/>
		</FileTreeProvider>
	);
});

type FileTreeSidecarProps = {
	currentControlled: boolean;
	currentPath?: string;
	directoriesOnly: boolean;
	fileSystem: FileTreeFileSystem;
	limits: FileTreeLimits;
	onActivate?: (entry: FileTreeFileStat) => void;
	onNavigate?: (path: string) => void;
	onSelectionChange?: (path?: string) => void;
	rootPath: string;
	selectedControlled: boolean;
	selectedPath?: string;
};

function FileTreeSidecar({
	currentControlled,
	currentPath,
	directoriesOnly,
	fileSystem,
	limits,
	onActivate,
	onNavigate,
	onSelectionChange,
	rootPath,
	selectedControlled,
	selectedPath,
}: FileTreeSidecarProps) {
	const store = useFileTreeStoreContext();
	const callbacks = useRef({ currentControlled, onActivate, onNavigate, onSelectionChange, selectedControlled });
	callbacks.current = { currentControlled, onActivate, onNavigate, onSelectionChange, selectedControlled };

	useEffect(() => {
		store.getState().actions.replaceSource({ directoriesOnly, fileSystem, limits, rootPath });
		const runtime = createFileTreeRuntime(store);
		runtime.start();
		return runtime.dispose;
	}, [directoriesOnly, fileSystem, limits, rootPath, store]);

	useEffect(() => {
		if (selectedControlled) store.getState().actions.syncSelectedPath(selectedPath);
	}, [selectedControlled, selectedPath, store]);

	useEffect(() => {
		if (currentControlled) store.getState().actions.syncCurrentPath(currentPath ?? rootPath);
	}, [currentControlled, currentPath, rootPath, store]);

	useEffect(() => {
		const events = store.getState().events;
		const offSelection = events.on(FileTreeEventType.SelectionRequested, ({ data }) => {
			if (!callbacks.current.selectedControlled) store.getState().actions.syncSelectedPath(data.path);
			callbacks.current.onSelectionChange?.(data.path);
		});
		const offNavigate = events.on(FileTreeEventType.NavigateRequested, ({ data }) => {
			if (!callbacks.current.currentControlled) store.getState().actions.syncCurrentPath(data.path);
			const entry = findFileTreeEntry(store.getState(), data.path);
			if (entry) callbacks.current.onActivate?.(entry);
			callbacks.current.onNavigate?.(data.path);
		});
		return () => {
			offSelection();
			offNavigate();
		};
	}, [store]);

	return null;
}

type FileTreeViewProps = Omit<ComponentPropsWithRef<'div'>, 'children'> & {
	ariaLabel: string;
	dropTarget?: FileTreeDropTarget;
	height: number;
	indent: number;
	isEntryDraggable?: FileTreeProps['isEntryDraggable'];
	messages: FileTreeMessages;
	onEntryDragEnd?: FileTreeProps['onEntryDragEnd'];
	onEntryDragLeave?: FileTreeProps['onEntryDragLeave'];
	onEntryDragOver?: FileTreeProps['onEntryDragOver'];
	onEntryDragStart?: FileTreeProps['onEntryDragStart'];
	onEntryDrop?: FileTreeProps['onEntryDrop'];
	renderIcon?: FileTreeProps['renderIcon'];
	renderLabel?: FileTreeProps['renderLabel'];
	rowHeight: number;
};

const FileTreeView = forwardRef<HTMLDivElement, FileTreeViewProps>(function FileTreeView(
	{
		ariaLabel,
		className,
		dropTarget,
		height,
		indent,
		isEntryDraggable,
		messages,
		onEntryDragEnd,
		onEntryDragLeave,
		onEntryDragOver,
		onEntryDragStart,
		onEntryDrop,
		renderIcon,
		renderLabel,
		rowHeight,
		style,
		...props
	},
	ref,
) {
	const state = useFileTreeStore((current) => current);
	const treeRef = useRef<TreeApi<FileTreeRenderNode> | undefined>(undefined);
	const data = useMemo(() => buildFileTreeData(state), [state]);
	const initialOpenState = useMemo(() => Object.fromEntries([...state.tree.expanded].map((path) => [path, true])), []);
	const renderNode = useCallback(
		(nodeProps: NodeRendererProps<FileTreeRenderNode>) => (
			<FileTreeNode
				{...nodeProps}
				dropTarget={dropTarget}
				isEntryDraggable={isEntryDraggable}
				messages={messages}
				onEntryDragEnd={onEntryDragEnd}
				onEntryDragLeave={onEntryDragLeave}
				onEntryDragOver={onEntryDragOver}
				onEntryDragStart={onEntryDragStart}
				onEntryDrop={onEntryDrop}
				onRetry={state.actions.retry}
				renderIcon={renderIcon}
				renderLabel={renderLabel}
			/>
		),
		[
			dropTarget,
			isEntryDraggable,
			messages,
			onEntryDragEnd,
			onEntryDragLeave,
			onEntryDragOver,
			onEntryDragStart,
			onEntryDrop,
			renderIcon,
			renderLabel,
			state.actions.retry,
		],
	);
	const rootDirectory = state.tree.directories.get(state.source.rootPath);

	useEffect(() => {
		const tree = treeRef.current;
		if (!tree) return;
		let changed = false;
		for (const [path, open] of Object.entries(tree.openState)) {
			if (open && !state.tree.expanded.has(path)) {
				tree.close(path, false);
				changed = true;
			}
		}
		const expanded = [...state.tree.expanded].sort((left, right) => left.length - right.length);
		for (const path of expanded) {
			if (!tree.isOpen(path)) {
				tree.open(path, false);
				changed = true;
			}
		}
		if (changed) tree.redrawList();
	}, [data, state.tree.expanded]);

	useEffect(() => {
		const tree = treeRef.current;
		if (tree && state.navigation.currentPath !== state.source.rootPath)
			void tree.scrollTo(state.navigation.currentPath);
	}, [data, state.navigation.currentPath, state.source.rootPath]);

	return (
		<div
			{...props}
			ref={ref}
			data-slot='file-tree'
			className={cn('border-base-300 bg-base-100 relative min-w-0 overflow-hidden rounded-md border', className)}
			style={{ height, ...style }}
		>
			<Tree<FileTreeRenderNode>
				ref={treeRef}
				aria-label={ariaLabel}
				childrenAccessor='children'
				data={data}
				dndBackend={fileTreeNoopDndBackend}
				disableDrag
				disableDrop
				disableEdit
				disableMultiSelection
				height={height}
				idAccessor='id'
				indent={indent}
				initialOpenState={initialOpenState}
				onActivate={(node) => state.actions.requestNavigate(node.data.path)}
				onSelect={(nodes) => {
					const path = nodes[0]?.data.path;
					if (path !== state.selection.path) state.actions.requestSelection(path);
				}}
				onToggle={(path) => {
					if (treeRef.current?.isOpen(path)) state.actions.expand(path);
					else state.actions.collapse(path);
				}}
				openByDefault={false}
				outerElementType={FileTreeScrollArea}
				overscanCount={6}
				renderRow={FileTreeRow}
				rowClassName='outline-none focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-info/60'
				rowHeight={rowHeight}
				selection={state.selection.path}
				width='100%'
			>
				{renderNode}
			</Tree>
			{dropTarget?.state === 'rejected' ? (
				<div className='sr-only' role='status'>
					{dropTarget.reason}
				</div>
			) : null}
			<FileTreeStatus
				directory={rootDirectory}
				messages={messages}
				onRetry={() => state.actions.retry(state.source.rootPath)}
			/>
		</div>
	);
});

function FileTreeStatus({
	directory,
	messages,
	onRetry,
}: {
	directory?: FileTreeDirectoryState;
	messages: FileTreeMessages;
	onRetry: () => void;
}) {
	if (!directory || directory.status === 'idle' || directory.status === 'loading' || directory.status === 'queued') {
		return (
			<div
				className='bg-base-100/90 pointer-events-none absolute inset-0 flex items-center justify-center gap-2 text-sm'
				role='status'
			>
				<LoaderCircle aria-hidden='true' className='text-info size-4 animate-spin' />
				{messages.loading}
			</div>
		);
	}
	if (directory.status === 'error') {
		return (
			<div
				className='bg-base-100/95 absolute inset-0 flex flex-col items-center justify-center gap-2 p-4 text-center text-sm'
				role='alert'
			>
				<TriangleAlert aria-hidden='true' className='text-error size-5' />
				<span>{formatFileTreeDirectoryError(directory, messages)}</span>
				<button type='button' className='btn btn-ghost btn-sm' onClick={onRetry}>
					<RotateCcw aria-hidden='true' className='size-4' />
					{messages.retry}
				</button>
			</div>
		);
	}
	if (directory.entries.length === 0) {
		return (
			<div
				className='text-base-content/60 pointer-events-none absolute inset-0 flex items-center justify-center text-sm'
				role='status'
			>
				{messages.empty}
			</div>
		);
	}
	return null;
}

const FileTreeScrollArea = forwardRef<HTMLDivElement, ComponentPropsWithRef<'div'>>(
	function FileTreeScrollArea(props, ref) {
		return <div {...props} ref={ref} />;
	},
);

function normalizeSize(value: number, fallback: number, minimum: number, maximum: number) {
	return Number.isFinite(value) ? Math.max(minimum, Math.min(Math.round(value), maximum)) : fallback;
}

function fileTreeNoopDndBackend() {
	const disconnect = () => undefined;
	return {
		connectDragPreview: () => disconnect,
		connectDragSource: () => disconnect,
		connectDropTarget: () => disconnect,
		profile: () => ({}),
		setup: () => undefined,
		teardown: () => undefined,
	};
}

function findFileTreeEntry(state: FileTreeStoreState, path: string) {
	for (const directory of state.tree.directories.values()) {
		const entry = directory.entries.find((candidate) => candidate.path === path);
		if (entry) return entry;
	}
	return undefined;
}

